const surfaceViews={
 moon:{image:"assets/images/moon-global-generated.png",source:"FULL MOON GLOBE · ILLUSTRATIVE GLOBAL VIEW",positions:[
  {mission:"apollo11",label:"Apollo 11 · Eagle",x:.63,y:.50},
  {mission:"apollo12-catalogue",label:"Apollo 12 · objects",x:.60,y:.53},
  {mission:"apollo14-catalogue",label:"Apollo 14 · objects",x:.43,y:.60},
  {mission:"apollo15-catalogue",label:"Apollo 15 · objects",x:.57,y:.41},
  {mission:"apollo16-catalogue",label:"Apollo 16 · objects",x:.49,y:.63},
  {mission:"apollo17-catalogue",label:"Apollo 17 · objects",x:.64,y:.60},
  {mission:"surveyor3",label:"Surveyor 3",x:.37,y:.52},
  {mission:"alsep",label:"ALSEP sites",x:.52,y:.36},
  {mission:"lrv",label:"Lunar Roving Vehicles",x:.70,y:.39},
 ]},
 mars:{image:"assets/images/mars-global-generated.png",source:"FULL MARS GLOBE · ILLUSTRATIVE GLOBAL VIEW",positions:[
  {mission:"sojourner",label:"Sojourner",x:.39,y:.39},
  {mission:"spirit",label:"Spirit",x:.82,y:.58},
  {mission:"opportunity",label:"Opportunity",x:.49,y:.51},
  {mission:"insight",label:"InSight",x:.78,y:.47},
  {mission:"ingenuity",label:"Ingenuity",x:.70,y:.40},
  {mission:"viking",label:"Viking 1 & 2",x:.32,y:.38},
  {mission:"phoenix",label:"Phoenix",x:.22,y:.18}
 ]},
 vesta:{image:null,source:"BEYOND · DISTINCT DESTINATIONS IN DEEP SPACE",positions:[]}
};
function applySurfaceTransform(){if(surfaceCanvas)surfaceCanvas.style.transform=`translate(${surfaceX}px,${surfaceY}px) scale(${surfaceScale})`;if(mapEl)mapEl.classList.toggle("zoomed-in",surfaceScale>1.28);}
function getFittedImageRect(){
 const img=document.getElementById("surfaceImage");if(!surfaceCanvas||!img)return null;
 const cw=surfaceCanvas.clientWidth,ch=surfaceCanvas.clientHeight,iw=img.naturalWidth||cw,ih=img.naturalHeight||ch;
 const scale=Math.min(cw/iw,ch/ih),width=iw*scale,height=ih*scale;
 return {left:(cw-width)/2,top:(ch-height)/2,width,height};
}
function positionSurfaceMarkers(){
 const fit=getFittedImageRect();if(!fit)return;
 const view=surfaceViews[activeSurfaceWorld];if(!view)return;
 document.querySelectorAll(".surface-marker").forEach(marker=>{
  const site=view.positions.find(p=>p.mission===marker.dataset.mission);if(!site)return;
  marker.style.left=`${fit.left+site.x*fit.width}px`;marker.style.top=`${fit.top+site.y*fit.height}px`;
 });
}
function resetSurfaceView(){surfaceScale=1.18;surfaceX=0;surfaceY=0;applySurfaceTransform();}
function zoomSurface(next,clientX,clientY){
 if(!surfaceCanvas)return;
 const rect=mapEl.getBoundingClientRect(),cx=clientX==null?rect.width/2:clientX-rect.left,cy=clientY==null?rect.height/2:clientY-rect.top;
 const old=surfaceScale,scale=Math.max(1,Math.min(4,next));
 const mx=rect.width/2,my=rect.height/2;
 const px=mx+(cx-mx-surfaceX)/old,py=my+(cy-my-surfaceY)/old;
 surfaceScale=scale;surfaceX=cx-mx-(px-mx)*scale;surfaceY=cy-my-(py-my)*scale;applySurfaceTransform();
}
function makeSurfaceMap(){
 mapEl.innerHTML='<div class="surface-canvas" id="surfaceCanvas"><img id="surfaceImage" alt="Zoomable planetary surface background"><div class="surface-markers" id="surfaceMarkers"></div></div><div class="surface-controls"><button type="button" id="zoomIn" aria-label="Zoom in">+</button><button type="button" id="zoomOut" aria-label="Zoom out">−</button><button type="button" id="zoomReset" aria-label="Reset zoom">⌂</button></div>';
 surfaceCanvas=document.getElementById("surfaceCanvas");
 document.getElementById("zoomIn").addEventListener("click",()=>zoomSurface(surfaceScale*1.35));
 document.getElementById("zoomOut").addEventListener("click",()=>zoomSurface(surfaceScale/1.35));
 document.getElementById("zoomReset").addEventListener("click",resetSurfaceView);
 if(!mapEl.dataset.panReady){
  mapEl.addEventListener("wheel",e=>{e.preventDefault();zoomSurface(surfaceScale*(e.deltaY<0?1.12:1/1.12),e.clientX,e.clientY);},{passive:false});
  mapEl.addEventListener("pointerdown",e=>{if(e.target.closest(".surface-marker,.surface-controls,.beyond-destination"))return;isPanning=true;panStart={x:e.clientX-surfaceX,y:e.clientY-surfaceY};mapEl.setPointerCapture(e.pointerId);mapEl.classList.add("panning");});
  mapEl.addEventListener("pointermove",e=>{if(!isPanning||!panStart)return;surfaceX=e.clientX-panStart.x;surfaceY=e.clientY-panStart.y;applySurfaceTransform();});
  const stop=()=>{isPanning=false;panStart=null;mapEl.classList.remove("panning");};
  mapEl.addEventListener("pointerup",stop);mapEl.addEventListener("pointercancel",stop);mapEl.addEventListener("lostpointercapture",stop);mapEl.dataset.panReady="true";
  if("ResizeObserver" in window){const observer=new ResizeObserver(()=>positionSurfaceMarkers());observer.observe(mapEl);}
  else window.addEventListener("resize",positionSurfaceMarkers);
 }
}
function focusSite(site){if(!site||!surfaceCanvas)return;const fit=getFittedImageRect();if(!fit)return;const scale=2.05;surfaceScale=scale;const x=fit.left+site.x*fit.width,y=fit.top+site.y*fit.height;surfaceX=-(x-mapEl.clientWidth/2)*scale;surfaceY=-(y-mapEl.clientHeight/2)*scale;applySurfaceTransform();}
function renderMapSites(key){
 const view=surfaceViews[key],container=document.getElementById("surfaceMarkers");if(!container)return;container.innerHTML="";activeSurfaceWorld=key;
 view.positions.forEach(site=>{
  const marker=document.createElement("button");marker.type="button";marker.className=`surface-marker ${key}`;marker.title=`Explore ${site.label}`;marker.setAttribute("aria-label",`Open ${site.label} story`);marker.innerHTML=`<span class="surface-marker-dot"></span><span class="surface-marker-label">${site.label}</span>`;
  marker.addEventListener("click",()=>{const mission=worldConfig[key].items.find(x=>x.id===site.mission);if(mission)showMissionDetail(mission,mission.id);});marker.dataset.mission=site.mission;container.appendChild(marker);
 });
 positionSurfaceMarkers();
 document.getElementById("mapMarkerCount").textContent=`${String(view.positions.length).padStart(2,"0")} MISSION SITES · APPROXIMATE GLOBE PLACEMENT`;
}

function renderBeyondCards(){
 if(!surfaceCanvas)return;
 try{resetSurfaceView()}catch(e){}
 surfaceCanvas.style.transform='none';
 const cards=[
  {id:"dawn-vesta",title:"Vesta",sub:"Dawn · 2011–2012",img:"assets/images/beyond-dawn-concept.jpg",alt:"Artist concept of Dawn spacecraft near asteroid Vesta"},
  {id:"dawn-ceres",title:"Ceres",sub:"Dawn · 2015–2018",img:"assets/images/nasa/PIA21906.jpg",fallback:"assets/images/ceres-orbital-visual.jpg",alt:"NASA Dawn image of dwarf planet Ceres"},
  {id:"near",title:"Eros",sub:"NEAR Shoemaker · 2001",img:"assets/images/beyond-near-concept.jpg",alt:"Artist concept of spacecraft near asteroid Eros"},
  {id:"pioneer10",title:"Outer Solar System",sub:"Pioneer 10 · 1972–2003",img:"assets/images/beyond-pioneer-concept.jpg",alt:"Artist concept of Pioneer 10 in deep space"},
  {id:"pioneer11",title:"Saturn & beyond",sub:"Pioneer 11 · 1973–1995",img:"assets/images/pioneer11-saturn-rings.jpeg",alt:"Saturn and its rings, encountered by Pioneer 11"},
  {id:"kepler",title:"Kepler field",sub:"Kepler telescope · 2009–2018",img:"assets/images/beyond-kepler-concept.jpg",alt:"Artist concept of Kepler space telescope"}
 ];
 surfaceCanvas.style.transform="none";surfaceCanvas.innerHTML=`<div class="beyond-destinations">${cards.map(c=>`<button class="beyond-destination" type="button" data-beyond-id="${c.id}"><img src="${c.img}" alt="${c.alt}" ${c.fallback?`onerror="this.onerror=null;this.src='${c.fallback}'"`:""}><span><b>${c.title}</b><small>${c.sub}</small></span></button>`).join("")}</div>`;
 surfaceCanvas.querySelectorAll("[data-beyond-id]").forEach(btn=>btn.addEventListener("click",()=>{const mission=worldConfig.vesta.items.find(x=>x.id===btn.dataset.beyondId);if(mission)showMissionDetail(mission,mission.id);}));
 const controls=mapEl.querySelector(".surface-controls");if(controls)controls.style.display="none";
 document.getElementById("mapMarkerCount").textContent="06 DESTINATIONS · NOT A SINGLE SURFACE MAP";
}
function closeMissionDetail(){
 const sidebar=document.querySelector(".mission-sidebar");sidebar.classList.remove("open");sidebar.setAttribute("aria-hidden","true");
 document.querySelectorAll(".surface-marker").forEach(x=>x.classList.remove("selected"));
}
function renderMissionWorld(key){
 const w=worldConfig[key],view=surfaceViews[key];if(!w)return;
 closeMissionDetail();
 const quizPanel=document.getElementById("quizDrawer");if(quizPanel){quizPanel.classList.remove("open");quizPanel.setAttribute("aria-hidden","true");}
 worldTabs.forEach(t=>{const active=t.dataset.world===key;t.classList.toggle("active",active);t.setAttribute("aria-selected",String(active));});
 document.getElementById("mapWorldName").textContent=w.name;
 document.getElementById("mapSourceLabel").textContent=view.source;
 if(key==="vesta"){
  mapEl.classList.add("archive-view");document.getElementById("mapHint").textContent="BEYOND THE PLANETS · TAP A MOVING DESTINATION";renderBeyondCards();resetSurfaceView();
 }else{
  if(!document.getElementById("surfaceImage"))makeSurfaceMap();
  const image=document.getElementById("surfaceImage");const controls=mapEl.querySelector(".surface-controls");if(controls)controls.style.display="grid";
  image.src=view.image;image.alt=key==="moon"?"Full-globe illustration of the Moon":"Full-globe illustration of Mars";image.style.display="block";image.onload=positionSurfaceMarkers;mapEl.classList.remove("archive-view");document.getElementById("mapHint").textContent="ZOOM TO REVEAL MISSION NAMES · DRAG TO PAN · SELECT A PIN";
  renderMapSites(key);resetSurfaceView();
 }
}
function showMissionDetail(m,id){
 const sidebar=document.querySelector(".mission-sidebar");sidebar.classList.add("open");sidebar.setAttribute("aria-hidden","false");
 const key=document.querySelector(".world-tab.active").dataset.world;
 document.querySelectorAll(".surface-marker").forEach(x=>x.classList.toggle("selected",x.dataset.mission===id));
 const photo=artifacts.find(a=>a.id===id&&a.image)||(
  id==="dawn-ceres"?{id:"dawn-ceres",name:"Dawn at Ceres",image:"assets/images/nasa/PIA21906.jpg",caption:"High-resolution view of Occator Crater on Ceres, observed by NASA’s Dawn spacecraft · NASA/JPL-Caltech/UCLA/MPS/DLR/IDA · PIA21906",fallbackImage:"assets/images/ceres-occator-closeup-visual.jpg",extraImage:"assets/images/nasa/PIA19167.jpg",extraCaption:"Ceres seen by Dawn during its approach · NASA/JPL-Caltech/UCLA/MPS/DLR/IDA · PIA19167",extraFallbackImage:"assets/images/ceres-orbital-visual.jpg"}:
  id==="dawn-vesta"?{id:"dawn-vesta",name:"Dawn at Vesta",image:"assets/images/nasa/PIA15384.jpg",caption:"Vesta as seen by NASA’s Dawn spacecraft · NASA/JPL-Caltech/UCLA/MPS/DLR/IDA · PIA15384"}:null
 );
 const extra=photo?.extraImage?`<figure class="detail-photo extra-photo"><img src="${photo.extraImage}" alt="${photo.name} additional mission image" ${photo.extraFallbackImage?`onerror="this.onerror=null;this.src='${photo.extraFallbackImage}';this.alt='AI-generated fallback illustration for ${photo.name}; not NASA imagery';this.closest('figure').querySelector('figcaption').textContent='AI-generated fallback illustration · not NASA imagery.'"`:`onerror="this.closest('figure').style.display='none'"`}><figcaption>${photo.extraCaption||"Additional mission image"}</figcaption></figure>`:"";
 const galleryMarkup=(photo?.galleryImages||[]).map((g,i)=>`<figure class="detail-photo extra-photo"><img src="${g.src}" alt="${photo.name} reference image ${i+1}" loading="lazy"><figcaption>${g.caption}</figcaption></figure>`).join("");
 const beyondArt=key==="vesta"?`<div class="beyond-illustration ${id}" role="img" aria-label="Artist's illustration representing ${m.name}"><span>${id==="dawn-vesta"||id==="dawn-ceres"?"DAWN":id==="near"?"NEAR SHOEMAKER":id==="pioneer10"?"PIONEER 10":"KEPLER"}</span><small>ARTIST'S CONCEPT · NOT A MISSION PHOTOGRAPH</small></div>`:"";
 const imageMarkup=photo?`<figure class="detail-photo"><img src="${photo.image}" alt="${photo.caption||photo.name}" ${photo.fallbackImage?`onerror="this.onerror=null;this.src='${photo.fallbackImage}';this.alt='AI-generated fallback illustration for ${photo.name}; not NASA imagery';this.closest('figure').querySelector('figcaption').textContent='AI-generated fallback illustration · not NASA imagery.'"`:`onerror="this.closest('figure').style.display='none'"`}><figcaption>${photo.caption||"Mission photograph · see source credit"}</figcaption></figure>${extra}`:beyondArt||`<div class="detail-no-photo">No photograph is shown for this panel. Read the story below and follow the NASA source link to see official images.</div>`;
 const d=document.getElementById("missionDetail");
 const full=artifacts.find(a=>a.id===id)||{};
 const story=m.story||full.story||m.summary||"Explore the mission record to learn more about this object.";
 const summary=full.summary||m.summary||"This mission left a lasting record in the exploration of the Solar System.";
 const detailFacts=key==="vesta"?({"dawn-vesta":"Dawn orbited Vesta from July 2011 to September 2012. Its instruments mapped the surface, measured the body's gravity and helped scientists understand Vesta as a differentiated protoplanet.","dawn-ceres":"Dawn entered orbit around Ceres in March 2015. It studied the dwarf planet's bright deposits, geology and evidence of water-related activity. When hydrazine was exhausted in 2018, Dawn could no longer point its antenna toward Earth; it remains in orbit.",near:"NEAR Shoemaker entered orbit around Eros in February 2000. After a year of close-up observations, it descended and touched down on February 12, 2001, returning data from the surface even though it was not built as a lander.",pioneer10:"Launched in March 1972, Pioneer 10 crossed the asteroid belt and flew past Jupiter in December 1973. Its weak final telemetry was received in January 2003. The spacecraft continues outward, but no longer sends usable signals.",pioneer11:"Pioneer 11 launched on April 6, 1973. It flew past Jupiter on December 3, 1974, then passed Saturn on September 1, 1979, becoming the first spacecraft to explore Saturn up close. It crossed Neptune’s orbital distance on February 23, 1990. NASA last contacted the spacecraft on September 30, 1995. A brief final set of engineering data was received on November 24, 1995. Pioneer 11 weighs about 570 pounds (258.5 kilograms) and carries a metal plaque shared in design with Pioneer 10. The plaque uses simple diagrams to show where the spacecraft came from and to offer a message to any future finder.",kepler:"Kepler observed more than 150,000 stars in its original field, looking for tiny, repeated dips in brightness caused by planets crossing in front of their stars. The mission ended in October 2018 after fuel ran out; its data transformed exoplanet science."})[id]:({apollo11:"Apollo 11 landed in the Sea of Tranquility on July 20, 1969. The Eagle's descent stage acted as the landing platform while the ascent stage carried Neil Armstrong and Buzz Aldrin back to lunar orbit. The stage was deliberately left behind to reduce the mass that had to be lifted off the Moon.","apollo12-catalogue":"The catalogue identifies the Apollo 12 landing area and lists objects such as the lunar module descent stage, central station, science instruments, camera equipment and astronaut tools. The crew also visited Surveyor 3, which had landed in 1967. NASA's catalogue is an inventory of objects; it does not give every object's exact position.","apollo14-catalogue":"Apollo 14 landed in the Fra Mauro region in February 1971. Its equipment list includes the central station, an ALSEP power source, seismic experiment hardware, tools and personal items. The real ALSEP photograph in this archive shows equipment during deployment. NASA's catalogue lists objects; it is not a coordinate map.","apollo15-catalogue":"Apollo 15 explored the Hadley–Apennine region in July 1971. The mission used the first lunar rover, allowing the astronauts to cover more ground and collect samples from several locations. The catalogue includes the rover, lunar module stages, science instruments, tools and personal items. The rover was parked on the Moon before the crew departed.","apollo16-catalogue":"Apollo 16 explored the Descartes Highlands in April 1972. The astronauts used a rover and deployed science instruments to study the local geology and lunar environment. The catalogue includes rover-related objects, experiment equipment, tools and personal items. NASA's catalogue is not a precise placement map.","apollo17-catalogue":"Apollo 17 landed in the Taurus–Littrow valley in December 1972 and was the final Apollo mission to send astronauts to the lunar surface. The crew used a rover, deployed a science station and collected samples. The catalogue records the descent stage, rover, instruments, tools and personal objects left at the site.",alsep:"ALSEP stands for Apollo Lunar Surface Experiments Package. Apollo 12, 14, 15, 16 and 17 crews deployed instrument stations; Apollo 11 carried an earlier, smaller package. Instruments included seismometers, heat-flow probes and other experiments. The network transmitted data until NASA shut it down on September 30, 1977.",lrv:"The Lunar Roving Vehicle was used on Apollo 15, 16 and 17. The battery-powered electric rover let astronauts travel several kilometres from the Lunar Module, carry tools and collect samples. Each rover was parked on the Moon before the crew launched back to orbit.",surveyor3:"Surveyor 3 made a soft landing in the Oceanus Procellarum on April 20, 1967. More than two years later, Apollo 12 astronauts Pete Conrad and Alan Bean landed nearby, examined the spacecraft and removed selected components. Those returned parts helped scientists study how lunar conditions affected materials.",sojourner:"Sojourner landed on Mars on July 4, 1997, as part of the Pathfinder mission. About the size of a microwave oven, it used six wheels and a small instrument package to inspect nearby rocks. The mission demonstrated that a compact rover could navigate another planet. Its last communication came in September 1997.",spirit:"Spirit landed in Gusev Crater in January 2004. It was designed for a 90-sol primary mission but continued for years, travelling about 7.7 kilometres. Spirit found evidence that water had altered rocks at the site. It became stuck in soft soil in 2009 and stopped communicating in March 2010.",opportunity:"Opportunity landed at Meridiani Planum in January 2004. Hematite-rich spherules and layered rocks provided evidence that liquid water had once affected the region. Designed for 90 sols, it operated for more than 14 years and travelled 45.16 kilometres. A planet-wide dust storm prevented its solar panels from recharging, and NASA ended the mission in 2019.",insight:"InSight landed on Mars in November 2018 to study the planet's interior. Its SEIS instrument detected marsquakes and meteorite impacts, while the mission's radio science helped reveal the size and structure of Mars' core. Dust accumulation reduced power, and the mission ended in December 2022 after contact was lost.",ingenuity:"Ingenuity arrived on Mars attached to the Perseverance rover and made the first powered, controlled flights on another planet in April 2021. The helicopter was intended for five flights but completed 72. Its final flight in January 2024 damaged rotor blades; it remains at its landing site and continues to serve as a technology milestone."})[id]||"";
 d.innerHTML=`<div class="detail-heading"><div><span class="detail-overline">${m.year} · ${key==="vesta"?"BEYOND THE PLANETS":"MISSION RECORD"}</span><h4>${m.name}</h4></div><button type="button" class="detail-close" id="closeMissionDetail" aria-label="Close mission details">×</button></div><span class="detail-status">${m.status}</span><div class="detail-type">${m.type}</div>${m.location?`<div class="detail-location"><b>LOCATION</b><span>${m.location}</span></div>`:""}${imageMarkup}${galleryMarkup}<p class="detail-summary">${summary}</p><h5 class="detail-section-title">The story behind the mission</h5><p class="detail-story">${story}</p>${leftBehindMarkup(m.id)}<div class="detail-plain-language"><b>IN SIMPLE WORDS</b><p>${m.id.startsWith("apollo")?"This record is a guide to objects that NASA's catalogue lists at this Apollo landing site. They are things astronauts used or left behind. Exact positions are not shown here.":m.id==="alsep"?"Think of ALSEP as a small science laboratory left on the Moon. Its instruments kept sending information to Earth after the astronauts went home.":m.id==="viking"?"Viking worked like two robotic science stations. They took pictures, tested soil and watched Martian weather without people standing nearby.":m.id==="phoenix"?"Phoenix was a robot explorer that dug into the cold soil near Mars’s north pole to look for water ice and study the ground.":m.id==="pioneer11"?"Pioneer 11 was a robot explorer that flew past Jupiter and Saturn. It sent its discoveries back to Earth by radio. It has gone too far away for us to keep in touch, but it is still travelling through space. Its plaque is like a tiny introduction from Earth to anyone who might find it one day.":"This mission left a machine or equipment that helped scientists learn about another world. Its story explains what it did, what happened to it and why it still matters."}</p></div>${detailFacts?`<h5 class="detail-section-title">What happened and why it matters</h5><p class="detail-story">${detailFacts}</p>`:""}<div class="detail-factline"><span>MISSION PERIOD</span><b>${m.year}</b></div><a class="detail-source" href="${m.source}" target="_blank" rel="noopener">Read the NASA mission record ↗</a>`;
 document.getElementById("closeMissionDetail").addEventListener("click",closeMissionDetail);
}

mapEl.addEventListener("click",e=>{const a=e.target.closest("[data-map-mission]");if(!a)return;e.preventDefault();const key=document.querySelector(".world-tab.active").dataset.world;const m=worldConfig[key].items.find(x=>x.id===a.dataset.mapMission);if(m)showMissionDetail(m,m.id);});
worldTabs.forEach(t=>t.addEventListener("click",()=>renderMissionWorld(t.dataset.world)));
makeSurfaceMap();

// Small, unobtrusive world-specific learning quiz.
const quizBank={
 moon:[{q:"What happened to Apollo 11's Eagle descent stage?",a:["It stayed at Tranquility Base","It returned to Earth","It entered lunar orbit"],c:0,why:"The descent stage served as the landing platform and remained on the Moon."},{q:"When was the Apollo seismic network switched off?",a:["1969","1977","1999"],c:1,why:"The Apollo seismic network stopped operating on September 30, 1977."},{q:"What did Apollo 12 do at Surveyor 3?",a:["Moved it to another crater","Returned selected parts to Earth","Restarted its engines"],c:1,why:"Conrad and Bean examined Surveyor 3 and brought selected components home."}],
 mars:[{q:"Which rover travelled about 45.16 kilometres?",a:["Spirit","Opportunity","Sojourner"],c:1,why:"Opportunity travelled 45.16 km during its long mission."},{q:"What did InSight listen for?",a:["Marsquakes","Solar flares","Jupiter storms"],c:0,why:"Its seismometer, SEIS, measured marsquakes and impacts."},{q:"How many flights did Ingenuity complete?",a:["5","27","72"],c:2,why:"Ingenuity far exceeded its five-flight technology demonstration plan."}],
 vesta:[{q:"Which spacecraft visited both Vesta and Ceres?",a:["Dawn","Kepler","Pioneer 10"],c:0,why:"Dawn orbited Vesta and then Ceres using ion propulsion."},{q:"Where did NEAR Shoemaker make its gentle touchdown?",a:["Mars","Eros","The Moon"],c:1,why:"NEAR Shoemaker touched down on asteroid 433 Eros in 2001."},{q:"What did Kepler search for?",a:["Moonquakes","Exoplanets","Martian ice"],c:1,why:"Kepler detected planets by measuring tiny dips in starlight."}]
};
let quizIndex=0,quizScore=0,quizAnswered=false;
const quizDrawer=document.getElementById("quizDrawer"),quizBody=document.getElementById("quizDrawerBody");
function openWorldQuiz(){const world=document.querySelector(".world-tab.active").dataset.world;quizIndex=0;quizScore=0;quizAnswered=false;document.getElementById("quizWorldTitle").textContent=(world==="vesta"?"Beyond":"The "+world)+" quiz";quizDrawer.classList.add("open");quizDrawer.setAttribute("aria-hidden","false");renderQuizQuestion();}
function renderQuizQuestion(){const world=document.querySelector(".world-tab.active").dataset.world,items=quizBank[world],q=items[quizIndex];if(!q){quizBody.innerHTML=`<div class="quiz-result"><strong>${quizScore} / ${items.length}</strong><p>${quizScore===3?"Excellent exploring!":"Nice work, explorer. Revisit the world and try again."}</p><button class="quiz-retry" id="quizRetry">Try again</button></div>`;document.getElementById("quizRetry").onclick=openWorldQuiz;return;}quizAnswered=false;quizBody.innerHTML=`<div class="quiz-progress">QUESTION ${quizIndex+1} OF ${items.length}</div><h4>${q.q}</h4><div class="quiz-options">${q.a.map((a,i)=>`<button data-answer="${i}">${a}</button>`).join("")}</div><p class="quiz-feedback" id="quizFeedback"></p><button class="quiz-next" id="quizNext" disabled>${quizIndex===items.length-1?"See my score":"Next question"} →</button>`;quizBody.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{if(quizAnswered)return;quizAnswered=true;const ok=Number(b.dataset.answer)===q.c;if(ok)quizScore++;quizBody.querySelectorAll("[data-answer]").forEach((x,i)=>{x.disabled=true;if(i===q.c)x.classList.add("correct");else if(x===b)x.classList.add("incorrect");});document.getElementById("quizFeedback").textContent=(ok?"That's right! ":"Not quite. ")+q.why;document.getElementById("quizNext").disabled=false;});document.getElementById("quizNext").onclick=()=>{quizIndex++;renderQuizQuestion();};}
document.getElementById("quizFab").addEventListener("click",openWorldQuiz);document.getElementById("quizClose").addEventListener("click",()=>{quizDrawer.classList.remove("open");quizDrawer.setAttribute("aria-hidden","true");});

renderMissionWorld("moon");

const grid=(document.getElementById("artifactGrid")||document.createElement("div"));
function renderArtifacts(filter="all"){grid.innerHTML=artifacts.filter(a=>filter==="all"||a.world===filter).map(a=>{const label=a.visualType||(a.image?"NASA MISSION IMAGE":"MISSION SYMBOL");const fallback=a.fallbackImage?`onerror="if(!this.dataset.fallback){this.dataset.fallback='1';this.src='${a.fallbackImage}';this.alt='AI-generated fallback illustration for ${a.name}; not a NASA photograph';this.parentElement.querySelector('.visual-credit-tag').textContent='AI-GENERATED FALLBACK · NOT NASA IMAGERY';}else{this.style.display='none';}"`:"";return `<article class="artifact-card" tabindex="0" role="button" data-id="${a.id}" aria-label="Read ${a.name}"><div class="artifact-visual ${a.world==="mars"?"mars-bg":a.world==="beyond"?"beyond-bg":""}">${a.image?`<img src="${a.image}" alt="${(a.caption||a.name).replace(/"/g,"&quot;")}" loading="lazy" ${fallback}>`:`<span class="glyph">${a.glyph}</span>`}${a.image?`<span class="visual-credit-tag">${label}</span>`:""}</div><div class="artifact-body"><span class="tag">${a.world==="moon"?"THE MOON":a.world==="mars"?"MARS":"BEYOND"} · ${a.year}</span><h3>${a.name}</h3><p>${a.summary}</p><span class="status">${a.status}</span></div></article>`;}).join("");}
renderArtifacts();
document.querySelectorAll(".filter").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".filter").forEach(x=>x.classList.remove("active"));b.classList.add("active");renderArtifacts(b.dataset.filter)}));
const modal=document.getElementById("storyModal"),modalContent=document.getElementById("modalContent");
function openStory(id){const a=artifacts.find(x=>x.id===id);if(!a)return;const rover=a.id==="spirit"||a.id==="opportunity";modalContent.innerHTML=`<span class="tag">${a.world.toUpperCase()} · ${a.year}</span><h2 id="modalTitle">${a.name}</h2><p><strong>${a.kind}</strong> · ${a.status}</p>${a.image?`<figure class="story-figure"><img src="${a.image}" alt="NASA image for ${a.name}" loading="lazy"><figcaption>${a.caption||"NASA mission image"}</figcaption></figure>`:""}${a.extraImage?`<figure class="story-figure"><img src="${a.extraImage}" alt="NASA animation showing ${a.name} instrument deployment" loading="lazy"><figcaption>${a.extraCaption||"NASA animation"}</figcaption></figure>`:""}<p>${a.story}</p><p>${a.summary}</p>${rover?`<div class="distance-panel"><h3>Going the distance</h3><div class="distance-stats"><div><b>7.7 km</b><span>Spirit travelled</span></div><div><b>45.16 km</b><span>Opportunity travelled</span></div></div><small>Distance figures are presented as project reference values; consult the linked mission records for context and updates.</small></div>`:""}<a href="${a.source}" target="_blank" rel="noopener">Read the NASA mission record ↗</a>`;modal.classList.add("open");modal.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";}
function closeModal(){modal.classList.remove("open");modal.setAttribute("aria-hidden","true");document.body.style.overflow="";}
grid.addEventListener("click",e=>{const card=e.target.closest(".artifact-card");if(card)openStory(card.dataset.id)});grid.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.classList.contains("artifact-card")){e.preventDefault();openStory(e.target.dataset.id)}});
modal.addEventListener("click",e=>{if(e.target.hasAttribute("data-close"))closeModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
document.getElementById("menuToggle").addEventListener("click",()=>document.getElementById("mainNav").classList.toggle("open"));
document.querySelectorAll("#mainNav a").forEach(a=>a.addEventListener("click",()=>document.getElementById("mainNav").classList.remove("open")));

const timeline=[
["1967","Surveyor 3 lands","A robotic precursor demonstrates soft landing technology on the Moon."],
["1969","Apollo seismic network begins","ALSEP instruments are deployed and begin returning lunar science."],
["1977","Apollo seismic operations end","The Apollo Passive Seismic Experiment network is switched off."],
["1997","Sojourner explores Mars","The first successful Mars rover demonstrates mobile surface exploration."],
["2004","Spirit & Opportunity arrive","Twin rovers begin a remarkable exploration of Mars."],
["2018","Opportunity's final signal","A global dust event ends communication with the rover."],
["2022","InSight mission ends","The lander can no longer maintain sufficient power."],
["2024","Ingenuity's final flight","Rotor damage ends the first powered flight campaign on another planet."]

];
(document.getElementById("timelineList")||document.createElement("div")).innerHTML=timeline.map(t=>`<div class="time-item"><b>${t[0]}</b><h3>${t[1]}</h3><p>${t[2]}</p></div>`).join("");

let catalog=[],shown=12,filtered=[];
const fmt=n=>Number(n).toLocaleString("en-US");
function renderTable(){const tbody=document.getElementById("dataRows");const rows=filtered.slice(0,shown);tbody.innerHTML=rows.map(r=>`<tr><td>${r.Y??"—"}</td><td>${r.JD??"—"}</td><td>${r.S??"—"}</td><td>${r.E??"—"}</td><td>${r.Grade??"—"}</td><td>${r.Traces??"—"}</td><td>${String(r.COMMENTS??"—").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])).slice(0,90)}</td></tr>`).join("")||'<tr><td colspan="7">No matching records.</td></tr>';document.getElementById("tableCount").textContent=`Showing ${fmt(rows.length)} of ${fmt(filtered.length)} matching records` ;document.getElementById("showMore").style.display=shown>=filtered.length?"none":"inline-flex";}
function searchCatalog(){const q=document.getElementById("dataSearch").value.toLowerCase().trim();filtered=!q?catalog:catalog.filter(r=>Object.values(r).some(v=>String(v??"").toLowerCase().includes(q)));shown=12;renderTable();}
function drawYearChart(summary){const box=document.getElementById("yearChart");const vals=Object.entries(summary.year_counts).sort((a,b)=>Number(a[0])-Number(b[0]));const max=Math.max(...vals.map(x=>x[1]));box.innerHTML=vals.map(([year,n])=>`<div class="bar-col"><span class="bar-val">${fmt(n)}</span><div class="bar" style="height:${Math.max(3,n/max*135)}px"></div><span class="bar-year">${year}</span></div>`).join("");}
function drawMoonMap(rows){const map=document.getElementById("moonMap");const valid=rows.filter(r=>Number.isFinite(Number(r.Lat))&&Number.isFinite(Number(r.Long)));valid.forEach(r=>{const x=(Number(r.Long)+180)/360*100,y=(90-Number(r.Lat))/180*100;const p=document.createElement("span");p.className="map-point "+(/LM|S-IVB|impact/i.test(String(r.Type))?"impact":"");p.style.left=x+"%";p.style.top=y+"%";p.title=`${r.Type||"Catalog entry"} · Lat ${r.Lat}, Long ${r.Long}`;map.appendChild(p);});}
Promise.all([fetch("data/main_catalog.json").then(r=>{if(!r.ok)throw Error("Catalog file missing");return r.json()}),fetch("data/summary.json").then(r=>r.json()),fetch("data/location_catalog.json").then(r=>r.json())]).then(([records,summary,locations])=>{catalog=records;filtered=catalog;document.getElementById("recordCount").textContent=fmt(summary.records);drawYearChart(summary);drawMoonMap(locations);renderTable();}).catch(err=>{document.getElementById("dataRows").innerHTML='<tr><td colspan="7">Could not load the local data files. Please run the site through the local server described in README.</td></tr>';document.getElementById("tableCount").textContent="Data unavailable";console.error(err);});
document.getElementById("dataSearch").addEventListener("input",searchCatalog);document.getElementById("showMore").addEventListener("click",()=>{shown+=20;renderTable()});

const questions=[
{q:"What did the Apollo ALSEP packages do?",opts:["Carry astronauts home","Collect scientific measurements on the Moon","Drive across the Moon"],a:1,why:"ALSEP included experiments such as seismometers that transmitted science data after the crews departed."},
{q:"Which rover explored Mars for more than 14 Earth years?",opts:["Sojourner","Opportunity","Spirit"],a:1,why:"Opportunity operated from 2004 until its final communication in 2018."},
{q:"What happened to Ingenuity?",opts:["It flew back to Earth","It became a Mars orbiter","Rotor damage ended its flights"],a:2,why:"Ingenuity completed 72 flights before rotor damage during its final flight ended flight operations."}
];let qi=0,score=0;
const quizArea=document.getElementById("quizArea");
(document.getElementById("startQuiz")||document.createElement("div")).addEventListener("click",()=>{qi=0;score=0;showQuestion()});
function showQuestion(){if(qi>=questions.length){quizArea.innerHTML=`<h3>Mission complete!</h3><p>You scored ${score} out of ${questions.length}. ${score===3?"Outstanding explorer!":"Every great explorer keeps learning."}</p><button class="button primary" id="retryQuiz">Try again ↻</button>`;document.getElementById("retryQuiz").addEventListener("click",()=>{qi=0;score=0;showQuestion()});return;}const q=questions[qi];quizArea.innerHTML=`<p><strong>Question ${qi+1} of ${questions.length}:</strong> ${q.q}</p><div class="quiz-options">${q.opts.map((o,i)=>`<button data-answer="${i}">${o}</button>`).join("")}</div><div class="quiz-feedback" id="quizFeedback"></div>`;quizArea.querySelectorAll("button[data-answer]").forEach(b=>b.addEventListener("click",()=>{const correct=Number(b.dataset.answer)===q.a;if(correct)score++;quizArea.querySelectorAll("button").forEach(x=>x.disabled=true);document.getElementById("quizFeedback").textContent=(correct?"Correct! ":"Not quite. ")+q.why;const next=document.createElement("button");next.className="button primary";next.style.marginTop="12px";next.textContent=qi===questions.length-1?"See result":"Next question →";next.addEventListener("click",()=>{qi++;showQuestion()});quizArea.appendChild(next);}));}

window.addEventListener("resize",()=>{if(activeSurfaceWorld!=="vesta")positionSurfaceMarkers();});



