function leftBehindMarkup(id){
 const d=LEFT_BEHIND[id];if(!d)return"";
 const esc=t=>String(t).replace(/&/g,"&amp;").replace(/</g,"&lt;");
 return `<div class="left-behind"><h5 class="detail-section-title">Left behind on the Moon</h5>${d.groups.map(g=>`<div class="lb-group"><b>${esc(g[0])}</b><ul>${g[1].map(i=>`<li>${esc(i)}</li>`).join("")}</ul></div>`).join("")}<p class="lb-fact">${esc(d.fact)}</p><small class="lb-source">Items and counts as listed in NASA's 2012 Catalogue of Manmade Material on the Moon (a selection, not every item). Exact positions are not shown.</small></div>`;
}

/* ---- Image safety net: local file -> official NASA-hosted copy -> "view on NASA" card ---- */
(()=>{
 const NASA_AS='https://assets.science.nasa.gov/dynamicimage/assets/science/psd/lunar-science/2023/09/';
 const PJ='https://photojournal.jpl.nasa.gov/jpeg/';
 const REMOTE={
  'as11-40-5927_orig.jpg':{src:NASA_AS+'as11-40-5927_orig.jpg?crop=faces%2Cfocalpoint&fit=clip&h=4095&w=4095',page:'https://science.nasa.gov/resource/view-apollo-11-lunar-module-as-it-rested-on-lunar-surface/'},
  'as15-85-11471_orig.jpg':{src:NASA_AS+'as15-85-11471_orig.jpg?crop=faces%2Cfocalpoint&fit=clip&h=4026&w=3928',page:'https://science.nasa.gov/resource/apollo-15-mission-image-view-of-the-apollo-lunar-surface-experiments-package-alsep/'},
  'PIA00381.jpg':{src:PJ+'PIA00381.jpg',page:'https://photojournal.jpl.nasa.gov/catalog/PIA00381'},
  'PIA00396.jpg':{src:PJ+'PIA00396.jpg',page:'https://photojournal.jpl.nasa.gov/catalog/PIA00396'},
  'PIA15384.jpg':{src:PJ+'PIA15384.jpg',page:'https://science.nasa.gov/photojournal/dawn-on-vesta/'},
  'PIA19167.jpg':{src:PJ+'PIA19167.jpg',page:'https://science.nasa.gov/photojournal/ceres-from-dawn-processed/'},
  'PIA21906.jpg':{src:PJ+'PIA21906.jpg',page:'https://science.nasa.gov/photojournal/high-resolution-ceres-view/'}
 };
 document.addEventListener('error',ev=>{
  const img=ev.target;
  if(!img||img.tagName!=='IMG')return;
  const info=REMOTE[(img.getAttribute('src')||'').split('?')[0].split('/').pop()];
  if(!info)return;
  if(!img.dataset.remoteTried){img.dataset.remoteTried='1';ev.stopImmediatePropagation();img.src=info.src;return;}
  if((img.getAttribute('onerror')||'').includes('AI-generated'))return; /* labelled AI fallback handles it */
  const fig=img.closest('figure');
  if(!fig)return;
  ev.stopImmediatePropagation();
  const cap=fig.querySelector('figcaption'),text=cap?cap.textContent:'NASA photograph';
  fig.innerHTML='<div class="img-missing"><b>NASA photograph</b><span></span><a target="_blank" rel="noopener">View the original on NASA ↗</a></div>';
  fig.querySelector('span').textContent=text;
  fig.querySelector('a').href=info.page;
 },true);
})();

